script.source:
if (ctx.weaponType !== "Shotgun" || ctx.damageType !== "Resolve" || ctx.damageValue <= 0) return false;
const choice = await H.ask.one({
  title: "Knockback", hint: "Reposition one Hunter in Close, or remove 1 Threat from your area?",
  options: [
    { value: "move", label: "Reposition a Hunter in Close" },
    { value: "threat", label: "Remove 1 Threat from your area" },
  ],
  buttonChoices: true, cancelLabel: "Skip",
});
if (!choice) return false;
if (choice === "move") await H.chat.post(`${actor.name} — Knockback: reposition one Hunter in Close.`, actor);
else await H.threat.remove(actor, 1, H.zone.of(actor));
